<script lang="ts">
 import {onMount} from 'svelte';import {api,graph,documents,message} from '$lib/workspace';import type {Graph} from '$lib/types';import Icon from '$lib/Icon.svelte';
 let error='',selected='';onMount(()=>{void api.call<Graph>('content_graph').then(result=>{if(result)graph.set(result);}).catch(e=>error=message(e));});
 $: edges=$graph.edges.filter(e=>!selected||e.from===selected||e.to===selected);
 function title(id:string){return $graph.nodes.find(n=>n.id===id)?.title||'Related document';}
 function url(id:string){const doc=$documents.find(d=>d.revision.document_id===id);return doc?(doc.doc_type==='experiment'?'/experiments/':'/documents/')+'?id='+id:null;}
</script>
<div class="page-heading"><span class="eyebrow">FOLLOW THE THREADS</span><h1>Nothing grows alone.</h1><p>See how your interests, experiments, stories, and projects connect.</p></div><div class="connections-toolbar"><span class="private-badge"><Icon name="lock" size={13}/> Your personal connections</span><select bind:value={selected} aria-label="Focus on a document"><option value="">All connections</option>{#each $documents as doc}<option value={doc.revision.document_id}>{doc.title}</option>{/each}</select></div>{#if error}<p class="alert" role="alert">{error}</p>{/if}<div class="connections-list">{#each edges as edge}<article class="connection-row"><span class="connection-dot"><Icon name="leaf" size={21}/></span><div class="connection-node">{#if url(edge.from)}<a href={url(edge.from)}>{title(edge.from)}</a>{:else}<strong>{title(edge.from)}</strong>{/if}<small>YOUR DOCUMENT</small></div><div class="connection-relation"><span>{edge.relation.replace(/_/g,' ')}</span><div><span></span><Icon name="arrow" size={17}/></div></div><div class="connection-node">{#if url(edge.to)}<a href={url(edge.to)}>{title(edge.to)}</a>{:else}<strong>{title(edge.to)}</strong>{/if}<small>CONNECTED WORK</small></div></article>{:else}<div class="empty-card"><Icon name="graph" size={34}/><h2>A thread begins with an interest.</h2><p>Create an experiment from an interest in your library. Its steps and stories will become part of this map.</p><a class="button secondary" href="/library/">Visit your library<Icon name="arrow" size={16}/></a></div>{/each}</div>{#if $graph.references.some(r=>r.target.url)}<section class="external-references"><h2>Ideas from elsewhere</h2>{#each $graph.references.filter(r=>r.target.url) as reference}<a class="interest-row" href={reference.target.url} target="_blank" rel="noopener noreferrer"><Icon name="book" size={19}/><div><strong>{reference.target.title||reference.target.url}</strong><p>{title(reference.source)} · {reference.relation.replace(/_/g,' ')}</p></div><span>↗</span></a>{/each}</section>{/if}
